      state::StateCommand getCommand(const std::string& trajectoryId,
                                     const TrajectoryExecutor::Point& playerPoint,
                                     TrajectoryPauseReason pauseReason,
                                     const state::StateCommand::SetIOs& setIOsCommand,
                                     std::chrono::system_clock::time_point startTime) {
         auto convertToExecutionState = [](const TrajectoryPauseReason& pauseReason) {
            using enum TrajectoryPauseReason;
            switch (pauseReason) {
               case USER_PAUSED:
                  return state::trajectory::ExecutionState::USER_PAUSED;
               case WAITING_FOR_IO:
                  return state::trajectory::ExecutionState::WAITING_FOR_IO;
               case STOPPED_ON_IO:
                  return state::trajectory::ExecutionState::STOPPED_ON_IO;
               case STOPPED:
                  return state::trajectory::ExecutionState::STOPPED;
               default:
                  return state::trajectory::ExecutionState::END_OF_TRAJECTORY;
            }
         };

         state::trajectory::ExecutionState executionState = playerPoint.isRunning ? state::trajectory::ExecutionState::RUNNING
                                                                                  : convertToExecutionState(pauseReason);

         state::MotionCommand motionCommand{ .jointPosition = playerPoint.jointPosition,
                                             .jointVelocity = playerPoint.jointVelocity,
                                             .executionDetails = state::trajectory::Details{ .trajectoryId = trajectoryId,
                                                                                             .location = playerPoint.location,
                                                                                             .timeToMotionEnd = playerPoint.timeToMotionEnd,
                                                                                             .executionState = executionState } };

         return { .motionCommand = motionCommand, .startTime = startTime, .setIOsCommand = setIOsCommand };
      }

      bool withinStandstillThreshold(const wb::math::Vector& lhs,
                                     const wb::math::Vector& rhs,
                                     const std::vector<wb::datamodels::DHParameter>& dhParameters) {
         const double threshold = safety::StandStillDetector::isLinearAxis(dhParameters)
                                     ? safety::StandStillDetector::STANDSTILL_THRESHOLD_MM
                                     : safety::StandStillDetector::STANDSTILL_THRESHOLD_RAD;
         return threshold > (lhs - rhs).cwiseAbs().maxCoeff();
      }
   }

