void setExecutionDetails(const internal::trajectory::Details& raeTrajectory,
                         wb::rae::v2::types::ExecutionState_Details* protoDetails) {
   protoDetails->set_kind(MotionKind::TRAJECTORY);
   protoDetails->set_trajectory(raeTrajectory.trajectoryId);
   protoDetails->set_location(raeTrajectory.location);

   auto* protoTrajectoryState = protoDetails->mutable_state();

   // Map pause reason to discriminator
   switch (raeTrajectory.executionState) {
      using enum internal::trajectory::ExecutionState;
      case STOPPED:
      case USER_PAUSED:
         protoTrajectoryState->set_kind(ProtoState::PAUSED_BY_USER);
         break;
      case WAITING_FOR_IO:
         protoTrajectoryState->set_kind(ProtoState::WAIT_FOR_IO);
         break;
      case STOPPED_ON_IO:
         protoTrajectoryState->set_kind(ProtoState::PAUSED_ON_IO);
         break;
      case END_OF_TRAJECTORY:
         protoTrajectoryState->set_kind(ProtoState::END_OF_TRAJECTORY);
         break;
      case RUNNING:
         protoTrajectoryState->set_kind(ProtoState::RUNNING);

         // Convert time to end from duration to milliseconds
         auto timeToMotionEnd = std::chrono::round<std::chrono::duration<uint32_t, std::milli>>(raeTrajectory.timeToMotionEnd);
         protoTrajectoryState->set_time_to_end(timeToMotionEnd.count());
   }
